// App Service Initialization
// Bootstraps background services, health monitoring, and recovery mechanisms

import { backgroundManager } from "./backgroundServiceManager";
import { recoveryManager } from "./serviceRecoveryManager";
import { healthCheckService } from "./healthCheckService";
import { checkHealth, clearCache } from "./clientAdapters";

/**
 * Initialize all background services and monitoring
 * Call this once when the app loads
 */
export async function initializeServices(): Promise<void> {
  console.info("[Init] Starting service initialization...");

  try {
    // 1. Start background service manager
    backgroundManager.start();

    // 2. Start service recovery manager
    recoveryManager.start();

    // 3. Perform initial health check
    console.info("[Init] Performing initial health check...");
    const health = await healthCheckService.performCheck();
    console.info("[Init] Initial health status:", health.status);

    // 4. Setup recovery listeners
    setupRecoveryListeners();

    // 5. Setup health monitoring interval
    setupHealthMonitoring();

    console.info("[Init] Service initialization complete!");
  } catch (_err) {
    void _err;
    (globalThis.console as any)?.error?.("[Init] Service initialization failed:", _err);
    throw _err;
  }
}

/**
 * Setup automatic recovery for failed services
 */
function setupRecoveryListeners(): void {
  console.debug("[Init] Setting up recovery listeners...");

  // Listen for API failures and trigger recovery
  const originalFetch = window.fetch;
  (window as any).fetch = async (...args: unknown[]) => {
    try {
      const response = await (originalFetch as any).apply(window, args as any);

      if (!response.ok && response.status >= 500) {
        // 5xx errors might indicate service issues
        console.warn(`[Init] API error detected: ${response.status}`);

        recoveryManager.scheduleRecovery(
          "api-endpoint",
          `HTTP ${response.status}`,
          async () => {
            await checkHealth();
          },
          2000
        );
      }

      return response;
    } catch (_err) {
      void _err;
      (globalThis.console as any)?.error?.("[Init] Fetch error:", _err);

      // Attempt to recover
      recoveryManager.scheduleRecovery(
        "api-endpoint",
        String(_err),
        async () => {
          await checkHealth();
        },
        3000
      );

      throw _err;
    }
  };
}

/**
 * Setup continuous health monitoring
 */
function setupHealthMonitoring(): void {
  console.debug("[Init] Setting up health monitoring...");

  // Check health every 60 seconds
  setInterval(async () => {
    try {
      const health = await healthCheckService.performCheck();

      if (health.status === "unhealthy") {
        console.warn("[Monitor] Health check returned unhealthy");

        recoveryManager.scheduleRecovery(
          "http-server",
          "Health check failed",
          async () => {
            await checkHealth();
          },
          1000
        );
      } else if (health.status === "degraded") {
        console.warn("[Monitor] Health check returned degraded");
      }

      // Log diagnostics periodically
      const stats = healthCheckService.getStats();
      console.debug("[Monitor] Health stats:", {
        endpoints: stats.sampledEndpoints,
        totalSamples: stats.totalSamples,
        avgResponseTimes: stats.avgResponseTimes,
      });
    } catch (_err) {
      void _err;
      (globalThis.console as any)?.error?.("[Monitor] Health monitoring error:", _err);
    }
  }, 60 * 1000);
}

/**
 * Get comprehensive system status
 */
export async function getSystemStatus(): Promise<{
  health: Awaited<ReturnType<typeof healthCheckService.performCheck>>;
  recovery: ReturnType<typeof recoveryManager.getStatus>;
  background: ReturnType<typeof backgroundManager.getStatus>;
}> {
  const [health, recovery, background] = await Promise.all([
    healthCheckService.performCheck(),
    Promise.resolve(recoveryManager.getStatus()),
    Promise.resolve(backgroundManager.getStatus()),
  ]);

  return { health, recovery, background };
}

/**
 * Gracefully shutdown all services
 */
export function shutdownServices(): void {
  console.info("[Shutdown] Shutting down services...");

  backgroundManager.stop();
  recoveryManager.stop();

  console.info("[Shutdown] All services stopped");
}

/**
 * Reset all caches and statistics
 */
export function resetAllCaches(): void {
  console.info("[Reset] Clearing all caches...");

  clearCache();
  healthCheckService.clearStats();
  recoveryManager.clearHistory();

  console.info("[Reset] All caches cleared");
}

/**
 * Enable debug logging
 */
export function enableDebugLogging(): void {
  console.info("[Debug] Debug logging enabled");

  // Intercept console methods to add timestamps
  const originalLog = (console as any).log;
  const originalWarn = (console as any).warn;
  const originalError = (console as any).error;

  (console as any).log = (...args: unknown[]) => {
    originalLog?.(`[${new Date().toISOString()}]`, ...(args as any));
  };

  (console as any).warn = (...args: unknown[]) => {
    originalWarn?.(`[${new Date().toISOString()}]`, ...(args as any));
  };

  (console as any).error = (...args: unknown[]) => {
    originalError?.(`[${new Date().toISOString()}]`, ...(args as any));
  };
}

/**
 * Get detailed diagnostic report
 */
export async function getDiagnosticReport(): Promise<{
  timestamp: number;
  uptime: number;
  health: Awaited<ReturnType<typeof healthCheckService.performCheck>>;
  recovery: ReturnType<typeof recoveryManager.getStatus>;
  background: ReturnType<typeof backgroundManager.getStatus>;
  memory?: NodeJS.MemoryUsage;
}> {
  const [health, recovery, background] = await Promise.all([
    healthCheckService.performCheck(),
    Promise.resolve(recoveryManager.getStatus()),
    Promise.resolve(backgroundManager.getStatus()),
  ]);

  return {
    timestamp: Date.now(),
    uptime: background.uptime,
    health,
    recovery,
    background,
    memory: typeof process !== "undefined" ? process.memoryUsage() : undefined,
  };
}

// Export singleton functions for CLI/testing access
export default {
  initializeServices,
  getSystemStatus,
  shutdownServices,
  resetAllCaches,
  enableDebugLogging,
  getDiagnosticReport,
};

// Background service manager for parallel operations and health monitoring
// Runs independently of UI, manages data sync, periodic health checks, and service recovery

import { checkHealth, fetchAllInParallel, clearCache } from "./clientAdapters";

export interface ServiceStatus {
  name: string;
  status: "healthy" | "degraded" | "unhealthy";
  lastCheck: number;
  error?: string;
  uptime: number;
}

interface BackgroundTask {
  id: string;
  name: string;
  interval: number;
  fn: () => Promise<void>;
  lastRun: number;
  nextRun: number;
  isRunning: boolean;
}

class BackgroundServiceManager {
  private tasks: Map<string, BackgroundTask> = new Map();
  private services: Map<string, ServiceStatus> = new Map();
  private startTime: number = Date.now();
  private pollInterval: NodeJS.Timeout | null = null;
  private enabled = false;

  constructor() {
    this.initializeServices();
  }

  // ========================================================================
  // SERVICE INITIALIZATION
  // ========================================================================

  private initializeServices(): void {
    // Register core services
    this.registerService("http", "HTTP Server", 8080);
    this.registerService("api-config", "API Configuration", undefined);
    this.registerService("adapters", "Client Adapters", undefined);
  }

  private registerService(id: string, name: string, port?: number): void {
    this.services.set(id, {
      name,
      status: "healthy",
      lastCheck: Date.now(),
      uptime: Date.now() - this.startTime,
    });
  }

  // ========================================================================
  // BACKGROUND TASK MANAGEMENT
  // ========================================================================

  registerTask(
    id: string,
    name: string,
    intervalMs: number,
    fn: () => Promise<void>
  ): void {
    this.tasks.set(id, {
      id,
      name,
      interval: intervalMs,
      fn,
      lastRun: 0,
      nextRun: Date.now() + intervalMs,
      isRunning: false,
    });
    console.debug(`[Background] Registered task: ${name} (${intervalMs}ms)`);
  }

  async executeTask(id: string): Promise<void> {
    const task = this.tasks.get(id);
    if (!task) return;

    if (task.isRunning) {
      console.warn(`[Background] Task ${id} already running, skipping`);
      return;
    }

    task.isRunning = true;
    const startTime = Date.now();

    try {
      await task.fn();
      task.lastRun = Date.now();
      task.nextRun = Date.now() + task.interval;
      console.debug(
        `[Background] Task ${id} completed in ${Date.now() - startTime}ms`
      );
    } catch (_err) {
      void _err;
      (globalThis.console as any)?.error?.(`[Background] Task ${id} failed:`, _err);
    } finally {
      task.isRunning = false;
    }
  }

  private async pollTasks(): Promise<void> {
    const now = Date.now();

    for (const [id, task] of this.tasks.entries()) {
      if (now >= task.nextRun && !task.isRunning) {
        await this.executeTask(id);
      }
    }
  }

  // ========================================================================
  // HEALTH MONITORING
  // ========================================================================

  async checkServiceHealth(): Promise<ServiceStatus> {
    try {
      const health = await checkHealth();
      return {
        name: "Backend API",
        status: health.status === "healthy" ? "healthy" : "degraded",
        lastCheck: Date.now(),
        uptime: Date.now() - this.startTime,
      };
    } catch (_err) {
      void _err;
      return {
        name: "Backend API",
        status: "unhealthy",
        lastCheck: Date.now(),
        error: String(_err),
        uptime: Date.now() - this.startTime,
      };
    }
  }

  async updateServiceStatus(
    id: string,
    status: "healthy" | "degraded" | "unhealthy",
    error?: string
  ): Promise<void> {
    const service = this.services.get(id);
    if (!service) return;

    service.status = status;
    service.lastCheck = Date.now();
    if (error) service.error = error;

    console.info(
      `[Health] ${service.name}: ${status}${error ? ` (${error})` : ""}`
    );
  }

  // ========================================================================
  // PUBLIC API
  // ========================================================================

  start(): void {
    if (this.enabled) {
      console.warn("[Background] Manager already running");
      return;
    }

    this.enabled = true;
    console.info("[Background] Starting background service manager...");

    // Setup default background tasks
    this.registerTask(
      "health-check",
      "Health Check",
      30 * 1000, // Every 30 seconds
      async () => {
        const status = await this.checkServiceHealth();
        this.services.set("backend", status);
      }
    );

    this.registerTask(
      "data-sync",
      "Data Sync",
      60 * 1000, // Every minute
      async () => {
        console.debug("[Background] Syncing data...");
        await fetchAllInParallel();
      }
    );

    this.registerTask(
      "cache-cleanup",
      "Cache Cleanup",
      10 * 60 * 1000, // Every 10 minutes
      async () => {
        const cleared = clearCache();
        if (cleared > 0) {
          console.debug(`[Background] Cleared ${cleared} cache entries`);
        }
      }
    );

    // Start polling loop
    this.pollInterval = setInterval(() => {
      this.pollTasks().catch((_err) => {
        (globalThis.console as any)?.error?.("[Background] Poll error:", _err);
      });
    }, 5 * 1000); // Check every 5 seconds

    console.info("[Background] Service manager started");
  }

  stop(): void {
    if (!this.enabled) return;

    this.enabled = false;
    if (this.pollInterval) {
      clearInterval(this.pollInterval as any);
      this.pollInterval = null;
    }

    console.info("[Background] Service manager stopped");
  }

  getStatus(): {
    enabled: boolean;
    uptime: number;
    services: ServiceStatus[];
    tasks: Array<{
      id: string;
      name: string;
      nextRun: number;
      isRunning: boolean;
    }>;
  } {
    return {
      enabled: this.enabled,
      uptime: Date.now() - this.startTime,
      services: Array.from(this.services.values()),
      tasks: Array.from(this.tasks.values()).map((t) => ({
        id: t.id,
        name: t.name,
        nextRun: t.nextRun,
        isRunning: t.isRunning,
      })),
    };
  }

  getTasks(): Array<{
    id: string;
    name: string;
    interval: number;
    lastRun: number;
    nextRun: number;
    isRunning: boolean;
  }> {
    return Array.from(this.tasks.values()).map((t) => ({
      id: t.id,
      name: t.name,
      interval: t.interval,
      lastRun: t.lastRun,
      nextRun: t.nextRun,
      isRunning: t.isRunning,
    }));
  }

  getServices(): ServiceStatus[] {
    return Array.from(this.services.values());
  }
}

// Export singleton instance
export const backgroundManager = new BackgroundServiceManager();

// Auto-start if in browser environment
if (typeof window !== "undefined") {
  // Start on next tick to allow imports to complete
  setTimeout(() => {
    backgroundManager.start();
  }, 100);
}

// Client-side adapters for production integrations with parallel execution support
// Features: Caching, retry logic, background operations, _request queuing, error recovery
// These call backend API endpoints (preferred) which should implement real third-party integrations.
// If the backend is not configured, these functions throw or return safe errors which the UI handles.

import { getEndpoint } from "../config/api";

// ============================================================================
// CONFIGURATION & CACHE MANAGEMENT
// ============================================================================

interface CacheEntry<T> {
  data: T;
  timestamp: number;
  ttl: number;
}

interface RequestQueue {
  pending: Map<string, Promise<unknown>>;
  retries: Map<string, number>;
}

// In-memory cache for adapter results (TTL-based)
const cache = new Map<string, CacheEntry<unknown>>();
const requestQueue: RequestQueue = {
  pending: new Map(),
  retries: new Map(),
};

const CACHE_TTL = {
  media: 5 * 60 * 1000, // 5 minutes
  verify: 10 * 60 * 1000, // 10 minutes
  mail: 0, // No cache (real-time action)
  files: 0, // No cache (real-time action)
  emergency: 0, // No cache (critical action)
  youtube: 30 * 60 * 1000, // 30 minutes
};

const MAX_RETRIES = 3;
const RETRY_DELAY = 1000; // ms

// ============================================================================
// UTILITY FUNCTIONS
// ============================================================================

function getCacheKey(endpoint: string, _params?: unknown): string {
  return `${endpoint}:${JSON.stringify(_params || {})}`;
}

function isCacheValid<T>(entry: CacheEntry<T>): boolean {
  return Date.now() - entry.timestamp < entry.ttl;
}

function getFromCache<T>(key: string): T | null {
  const entry = cache.get(key);
  if (entry && isCacheValid(entry)) {
    console.debug(`[Cache HIT] ${key}`);
    return entry.data as any as T;
  }
  if (entry) cache.delete(key);
  return null;
}

function setCache<T>(
  key: string,
  data: T,
  endpoint: keyof typeof CACHE_TTL
): void {
  cache.set(key, {
    data,
    timestamp: Date.now(),
    ttl: CACHE_TTL[endpoint],
  });
}

async function withRetry<T>(
  fn: () => Promise<T>,
  endpoint: string,
  maxRetries = MAX_RETRIES
): Promise<T> {
  let lastError: unknown;
  for (let i = 0; i <= maxRetries; i++) {
    try {
      return await fn();
    } catch (_err) {
      void _err;
      lastError = _err;
      if (i < maxRetries) {
        const delay = RETRY_DELAY * Math.pow(2, i); // exponential backoff
        console.warn(
          `[Retry ${i + 1}/${maxRetries}] ${endpoint} in ${delay}ms`
        );
        await new Promise((resolve) => setTimeout(resolve, delay));
      }
    }
  }
  throw lastError;
}

async function deduplicateRequest<T>(
  key: string,
  fn: () => Promise<T>
): Promise<T> {
  if (requestQueue.pending.has(key)) {
    console.debug(`[Dedup] Reusing pending _request: ${key}`);
    return requestQueue.pending.get(key) as Promise<T>;
  }
  const promise = fn().finally(() => {
    requestQueue.pending.delete(key);
  });
  requestQueue.pending.set(key, promise);
  return promise;
}

// ============================================================================
// ADAPTER FUNCTIONS - WITH PARALLEL & BACKGROUND SUPPORT
// ============================================================================

export async function fetchMedia(forceRefresh = false): Promise<any[]> {
  const cacheKey = getCacheKey("media");

  // Check cache first (unless force refresh)
  if (!forceRefresh) {
    const cached = getFromCache<any[]>(cacheKey);
    if (cached) return cached;
  }

  return deduplicateRequest(cacheKey, async () => {
    return withRetry(async () => {
      const _res = await fetch(getEndpoint("media"), {
        signal: AbortSignal.timeout(30000), // 30s timeout
      });
      if (!_res.ok) throw new Error(`media fetch failed: ${_res.status}`);
      const data = await _res.json();
      const items = data.items || [];
      setCache(cacheKey, items, "media");
      return items;
    }, "fetchMedia");
  }).catch((_err) => {
    console.warn("fetchMedia error", _err);
    return [];
  });
}

export async function verifyProduct(
  query: string,
  forceRefresh = false
): Promise<string> {
  const cacheKey = getCacheKey("verify", { query });

  if (!forceRefresh) {
    const cached = getFromCache<string>(cacheKey);
    if (cached) return cached;
  }

  return deduplicateRequest(cacheKey, async () => {
    return withRetry(async () => {
      const _res = await fetch(
        `${getEndpoint("verify")}?q=${encodeURIComponent(query)}`,
        { signal: AbortSignal.timeout(30000) }
      );
      if (!_res.ok) throw new Error(`verify failed: ${_res.status}`);
      const data = await _res.json();
      const result = data.result || "No result";
      setCache(cacheKey, result, "verify");
      return result;
    }, "verifyProduct");
  }).catch((_err) => {
    console.warn("verifyProduct error", _err);
    return `Verification unavailable: ${String(_err)}`;
  });
}

export async function sendMail(payload: {
  to: string;
  subject: string;
  body: string;
}): Promise<boolean> {
  return withRetry(
    async () => {
      const _res = await fetch(getEndpoint("mail"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
        signal: AbortSignal.timeout(30000),
      });
      if (!_res.ok) throw new Error(`mail failed: ${_res.status}`);
      return true;
    },
    "sendMail",
    2
  ) // 2 retries for mail
    .catch((_err) => {
      console.warn("sendMail error", _err);
      return false;
    });
}

export async function uploadFile(formData: FormData): Promise<unknown> {
  return withRetry(
    async () => {
      const _res = await fetch(getEndpoint("files"), {
        method: "POST",
        body: formData,
        signal: AbortSignal.timeout(60000), // 60s timeout for large files
      });
      if (!_res.ok) throw new Error(`upload failed: ${_res.status}`);
      return await _res.json();
    },
    "uploadFile",
    2
  ).catch((_err) => {
    console.warn("uploadFile error", _err);
    return { success: false, error: String(_err) };
  });
}

export async function emergencyAction(
  action: string,
  payload: unknown
): Promise<unknown> {
  // Emergency actions skip retry logic for speed
  try {
    const _res = await fetch(getEndpoint("emergency"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action, payload }),
      signal: AbortSignal.timeout(10000), // 10s timeout for emergency
    });
    const result = await _res.json();
    console.info(`[Emergency] Action ${action} executed:`, result);
    return result;
  } catch (_err) {
    void _err;
    (globalThis.console as any)?.error?.("emergencyAction error", _err);
    return { ok: false, error: String(_err) };
  }
}

export async function youtubeDownload(url: string): Promise<unknown> {
  const cacheKey = getCacheKey("youtube", { url });

  const cached = getFromCache<unknown>(cacheKey);
  if (cached) return cached;

  return deduplicateRequest(cacheKey, async () => {
    return withRetry(async () => {
      const _res = await fetch(getEndpoint("youtube"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url }),
        signal: AbortSignal.timeout(60000),
      });
      if (!_res.ok) throw new Error(`youtube download failed: ${_res.status}`);
      const data = await _res.json();
      setCache(cacheKey, data, "youtube");
      return data;
    }, "youtubeDownload");
  }).catch((_err) => {
    console.warn("youtubeDownload error", _err);
    return { success: false, error: String(_err) };
  });
}

// ============================================================================
// PARALLEL EXECUTION HELPERS
// ============================================================================

export async function fetchAllInParallel(): Promise<{
  media: unknown[];
  health: unknown;
}> {
  console.debug("[Parallel] Fetching all resources in parallel...");
  const [media, health] = await Promise.allSettled([
    fetchMedia(),
    checkHealth(),
  ]);

  return {
    media: media.status === "fulfilled" ? media.value : [],
    health:
      health.status === "fulfilled" ? health.value : { status: "unknown" },
  };
}

export async function checkHealth(): Promise<{
  status: string;
  timestamp: string;
}> {
  try {
    const _res = await fetch(getEndpoint("health"), {
      signal: AbortSignal.timeout(5000),
    });
    if (_res.ok) {
      return { status: "healthy", timestamp: new Date().toISOString() };
    }
  } catch (_err) {
    void _err;
    console.warn("Health check failed", _err);
  }
  return { status: "degraded", timestamp: new Date().toISOString() };
}

// ============================================================================
// CACHE MANAGEMENT & CLEANUP
// ============================================================================

export function clearCache(pattern?: string): number {
  if (!pattern) {
    const size = cache.size;
    cache.clear();
    console.debug(`[Cache] Cleared all ${size} entries`);
    return size;
  }

  let cleared = 0;
  for (const key of cache.keys()) {
    if (key.includes(pattern)) {
      cache.delete(key);
      cleared++;
    }
  }
  console.debug(`[Cache] Cleared ${cleared} entries matching "${pattern}"`);
  return cleared;
}

export function getCacheStats(): {
  total: number;
  byEndpoint: { [key: string]: number };
} {
  const stats = {
    total: cache.size,
    byEndpoint: {} as { [key: string]: number },
  };

  for (const key of cache.keys()) {
    const endpoint = key.split(":")[0];
    stats.byEndpoint[endpoint] = (stats.byEndpoint[endpoint] || 0) + 1;
  }

  return stats;
}

export function getPendingRequests(): string[] {
  return Array.from(requestQueue.pending.keys());
}

// Cleanup stale cache entries every 10 minutes
if (typeof window !== "undefined") {
  setInterval(() => {
    let removed = 0;
    for (const [key, entry] of cache.entries()) {
      if (!isCacheValid(entry)) {
        cache.delete(key);
        removed++;
      }
    }
    if (removed > 0)
      console.debug(`[Cache] Cleaned up ${removed} stale entries`);
  }, 10 * 60 * 1000);
}

// Health check API endpoint with diagnostic information
// Provides comprehensive service health, cache statistics, and pending requests

import {
  checkHealth,
  getCacheStats,
  getPendingRequests,
} from "./clientAdapters";
import { backgroundManager } from "./backgroundServiceManager";

export interface HealthCheckResponse {
  timestamp: number;
  status: "healthy" | "degraded" | "unhealthy";
  system: {
    uptime: number;
    environment: string;
    serviceStatus: Record<string, string>;
  };
  adapters: {
    status: string;
    error?: string;
    cacheStats: {
      total: number;
      entries: Record<string, number>;
    };
    pendingRequests: string[];
  };
  backgroundServices: {
    enabled: boolean;
    uptime: number;
    activeServices: number;
    scheduledTasks: number;
  };
  diagnostics: {
    memoryUsage?: NodeJS.MemoryUsage;
    responseTimes: Record<string, number>;
  };
}

export class HealthCheckService {
  private responseTimes: Map<string, number[]> = new Map();
  private maxSamples = 100;

  // ========================================================================
  // RESPONSE TIME TRACKING
  // ========================================================================

  recordResponseTime(endpoint: string, ms: number): void {
    if (!this.responseTimes.has(endpoint)) {
      this.responseTimes.set(endpoint, []);
    }

    const times = this.responseTimes.get(endpoint)!;
    times.push(ms);

    if (times.length > this.maxSamples) {
      times.shift();
    }
  }

  getAverageResponseTime(endpoint: string): number {
    const times = this.responseTimes.get(endpoint);
    if (!times || times.length === 0) return 0;

    const sum = times.reduce((a, b) => a + b, 0);
    return Math.round(sum / times.length);
  }

  getAllResponseTimes(): Record<string, number> {
    const result: Record<string, number> = {};

    for (const [endpoint, times] of this.responseTimes.entries()) {
      if (times.length > 0) {
        const sum = times.reduce((a, b) => a + b, 0);
        result[endpoint] = Math.round(sum / times.length);
      }
    }

    return result;
  }

  // ========================================================================
  // HEALTH CHECK
  // ========================================================================

  async performCheck(): Promise<HealthCheckResponse> {
    const startTime = Date.now();

    try {
      // Get adapter health
      const adapterHealth = await checkHealth();

      // Get cache and pending data
      const cacheStats = getCacheStats();
      const pendingRequests = getPendingRequests();

      // Get background service status
      const bgStatus = backgroundManager.getStatus();

      // Determine overall status
      let overallStatus: "healthy" | "degraded" | "unhealthy" = "healthy";

      if (adapterHealth.status === "unhealthy") {
        overallStatus = "unhealthy";
      } else if (
        adapterHealth.status === "degraded" ||
        bgStatus.services.some((s) => s.status === "degraded")
      ) {
        overallStatus = "degraded";
      }

      const response: HealthCheckResponse = {
        timestamp: Date.now(),
        status: overallStatus,
        system: {
          uptime: Date.now() - startTime,
          environment: process.env.NEXT_PUBLIC_ENV || "development",
          serviceStatus: this.getServiceStatus(),
        },
        adapters: {
          status: adapterHealth.status,
          error: (adapterHealth as any).error,
          cacheStats: {
            total: cacheStats.total,
            entries: cacheStats.byEndpoint,
          },
          pendingRequests: pendingRequests.slice(0, 10), // Return top 10
        },
        backgroundServices: {
          enabled: bgStatus.enabled,
          uptime: bgStatus.uptime,
          activeServices: bgStatus.services.filter(
            (s) => s.status === "healthy",
          ).length,
          scheduledTasks: bgStatus.tasks.length,
        },
        diagnostics: {
          memoryUsage:
            typeof process !== "undefined" ? process.memoryUsage() : undefined,
          responseTimes: this.getAllResponseTimes(),
        },
      };

      this.recordResponseTime("health-check", Date.now() - startTime);
      return response;
    } catch (_err) { void _err;
      return {
        timestamp: Date.now(),
        status: "unhealthy",
        system: {
          uptime: Date.now() - startTime,
          environment: process.env.NEXT_PUBLIC_ENV || "development",
          serviceStatus: this.getServiceStatus(),
        },
        adapters: {
          status: "unhealthy",
          error: String(_err),
          cacheStats: { total: 0, entries: {} as Record<string, number> },
          pendingRequests: [],
        },
        backgroundServices: {
          enabled: false,
          uptime: 0,
          activeServices: 0,
          scheduledTasks: 0,
        },
        diagnostics: {
          responseTimes: {},
        },
      };
    }
  }

  // ========================================================================
  // UTILITIES
  // ========================================================================

  private getServiceStatus(): Record<string, string> {
    const status: Record<string, string> = {};

    // Check HTTP server
    if (typeof window !== "undefined") {
      status["http-server"] = "running";
    } else {
      status["http-server"] = "unavailable-in-node";
    }

    // Check API config
    const apiUrl = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8080";
    status["api-endpoint"] = apiUrl;

    // Background services
    const bgServices = backgroundManager.getServices();
    bgServices.forEach((s) => {
      status[`service-${s.name.toLowerCase().replace(/\s+/g, "-")}`] = s.status;
    });

    return status;
  }

  clearStats(): void {
    this.responseTimes.clear();
    console.info("[HealthCheck] Statistics cleared");
  }

  getStats(): {
    sampledEndpoints: number;
    totalSamples: number;
    avgResponseTimes: Record<string, number>;
  } {
    let totalSamples = 0;
    for (const times of this.responseTimes.values()) {
      totalSamples += times.length;
    }

    return {
      sampledEndpoints: this.responseTimes.size,
      totalSamples,
      avgResponseTimes: this.getAllResponseTimes(),
    };
  }
}

