        isSelected: false,
        tags: ["documentation", "projects"],
        category: "document",
      },
    ];

    setFiles(mockFiles);
  }, []);

  const filteredFiles = files.filter((file) => {
    const matchesSearch =
      file.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      file.tags.some((tag) =>
        tag.toLowerCase().includes(searchQuery.toLowerCase())
      );
    const matchesCategory =
      selectedCategory === "all" || file.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  const sortedFiles = [...filteredFiles].sort((a, b) => {
    let comparison = 0;

    switch (sortBy) {
      case "name":
        comparison = a.name.localeCompare(b.name);
        break;
      case "date":
        comparison =
          new Date(a.lastModified).getTime() -
          new Date(b.lastModified).getTime();
        break;
      case "size":
        comparison = (a.size || 0) - (b.size || 0);
        break;
      case "type":
        comparison = a.type.localeCompare(b.type);
        break;
    }

    return sortOrder === "asc" ? comparison : -comparison;
  });

  const handleFileSelect = useCallback((id: string) => {
    setFiles((prev) =>
      prev.map((file) => ({
        ...file,
        isSelected: file.id === id ? !file.isSelected : file.isSelected,
      }))
    );
  }, []);

  const handleBulkSelect = useCallback(() => {
    setFiles((prev) => prev.map((file) => ({ ...file, isSelected: true })));
  }, []);

  const handleBulkDeselect = useCallback(() => {
    setFiles((prev) => prev.map((file) => ({ ...file, isSelected: false })));
  }, []);

  const handleDelete = useCallback(async () => {
    const selectedFiles = files.filter((file) => file.isSelected);
    if (selectedFiles.length === 0) return;

    if (
      confirm(
        `Are you sure you want to delete ${selectedFiles.length} item(s)?`
      )
    ) {
      setIsLoading(true);
      try {
        // Simulate deletion
        await new Promise((resolve) => setTimeout(resolve, 1000));
        setFiles((prev) => prev.filter((file) => !file.isSelected));
      } catch (_e: unknown) {
        (globalThis.console as any)?.error?.("Error deleting files:", extractMessage(_e));
      } finally {
        setIsLoading(false);
      }
    }
  }, [files]);

  const handleOrganize = useCallback(async () => {
    setIsLoading(true);
    try {
      // Simulate AI organization
      await new Promise((resolve) => setTimeout(resolve, 2000));

      // AI would organize files by type, date, or other criteria
      setFiles((prev) =>
        prev.map((file) => ({
          ...file,
          tags: [...file.tags, "organized"],
        }))
      );
    } catch (error) {
      (globalThis.console as any)?.error?.("Error organizing files:", error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const getFileIcon = (file: FileItem) => {
    if (file.type === "folder") return "📁";

    switch (file.extension) {
      case ".ts":
      case ".tsx":
      case ".js":
      case ".jsx":
        return "📄";
      case ".md":
        return "📝";
      case ".json":
        return "⚙️";
      case ".py":
        return "🐍";
      case ".css":
      case ".scss":
        return "🎨";
      default:
        return "📄";
    }
  };

  const formatFileSize = (bytes?: number) => {
    if (!bytes) return "0 B";
    const sizes = ["B", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(1024));
    return `${(bytes / Math.pow(1024, i)).toFixed(1)} ${sizes[i]}`;
  };

  const categories = [
    { value: "all", label: "All Files", emoji: "📁" },
    { value: "project", label: "Projects", emoji: "🚀" },
    { value: "code", label: "Code", emoji: "💻" },
    { value: "document", label: "Documents", emoji: "📝" },
    { value: "media", label: "Media", emoji: "🎬" },
    { value: "data", label: "Data", emoji: "📊" },
    { value: "other", label: "Other", emoji: "📄" },
  ];

  const handleRequestWallet = async () => {
    try {
      setLoading(true);
      setError(null);
      const email = localStorage.getItem("userEmail");
      const username = localStorage.getItem("username");

      if (!email || !username) {
        throw new Error("Please complete your profile first");
      }

      const _res = await fetch("/api/wallet", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-admin-token": localStorage.getItem("adminToken") || "",
        },
        body: JSON.stringify({
          action: "request_wallet",
          email,
          username,
        }),
      });

      const data = await _res.json();

      if (data.status === "pending") {
        setWalletRequested(true);
        toast({
          title: "Success",
          description: "Wallet _request sent to master for approval",
        });
      } else {
        throw new Error(data.error || "Failed to _request wallet");
      }
    } catch (_e: unknown) {
      const msg = extractMessage(_e);
      setError(msg);
      toast({
        title: "Error",
        description: msg,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleApproveWallet = async (email: string) => {
    try {
      setLoading(true);
      setError(null);
      const _res = await fetch("/api/wallet", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-admin-token": localStorage.getItem("adminToken") || "",
          "x-master-token": localStorage.getItem("masterToken") || "",
        },
        body: JSON.stringify({
          action: "approve_wallet",
          email,
        }),
      });

      const data = await _res.json();

      if (data.status === "approved") {
        setPendingRequests((prev) => prev.filter((r) => r.email !== email));
        toast({
          title: "Success",
          description: `Wallet approved for ${email}`,
        });
      } else {
        throw new Error(data.error || "Failed to approve wallet");
      }
    } catch (_e: unknown) {
      const msg = extractMessage(_e);
      setError(msg);
      toast({
        title: "Error",
        description: msg,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-lg shadow-lg p-6">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">
            🤖 AI File Manager
          </h2>
          <p className="text-gray-600">
            Intelligent file organization and management
          </p>
        </div>
        <div className="text-right">
          <div className="text-sm text-gray-500">
            {getCurrentTime()} {currentTimezone.emoji}
          </div>
          <div className="text-xs text-gray-400">
            {files.length} items • {files.filter((f) => f.isSelected).length}{" "}
            selected
          </div>
        </div>
      </div>

      {/* Search and Filters */}
      <div className="flex flex-wrap gap-4 mb-6">
        <div className="flex-1 min-w-64">
          <input
            type="text"
            placeholder="🔍 Search files, folders, or tags..."
            value={searchQuery}
            onChange={(_e) => setSearchQuery(_e.target.value)}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          />
        </div>

        <select
          value={selectedCategory}
          onChange={(_e) => setSelectedCategory(_e.target.value)}
          className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
        >
          {categories.map((cat) => (
            <option key={cat.value} value={cat.value}>
              {cat.emoji} {cat.label}
            </option>
          ))}
        </select>

        <select
          value={sortBy}
          onChange={(_e) =>
            setSortBy(_e.target.value as "name" | "date" | "size" | "type")
          }
          className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
        >
          <option value="name">📝 Name</option>
          <option value="date">📅 Date</option>
          <option value="size">📏 Size</option>
          <option value="type">📁 Type</option>
        </select>

        <button
          onClick={() =>
            setSortOrder((prev) => (prev === "asc" ? "desc" : "asc"))
          }
          className="px-4 py-2 bg-gray-100 hover:bg-gray-200 rounded-lg transition-colors"
        >
          {sortOrder === "asc" ? "⬆️" : "⬇️"}
        </button>

        <button
          onClick={() =>
            setViewMode((prev) => (prev === "grid" ? "list" : "grid"))
          }
          className="px-4 py-2 bg-gray-100 hover:bg-gray-200 rounded-lg transition-colors"
        >
          {viewMode === "grid" ? "📋" : "🔲"}
        </button>
      </div>

      {/* Actions */}
      <div className="flex flex-wrap gap-2 mb-6">
        <button
          onClick={handleBulkSelect}
          className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors"
        >
          ☑️ Select All
        </button>
        <button
          onClick={handleBulkDeselect}
          className="px-4 py-2 bg-gray-500 text-white rounded-lg hover:bg-gray-600 transition-colors"
        >
          ☐ Deselect All
        </button>
        <button
          onClick={handleDelete}
          disabled={files.filter((f) => f.isSelected).length === 0}
          className="px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
        >
          🗑️ Delete Selected
        </button>
        <button
          onClick={handleOrganize}
          disabled={isLoading}
          className="px-4 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-colors disabled:opacity-50"
        >
          {isLoading ? "🔄 Organizing..." : "🤖 AI Organize"}
        </button>
      </div>

      {/* File Grid/List */}
      <div
        className={`grid gap-4 ${
          viewMode === "grid"
            ? "grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4"
            : "grid-cols-1"
        }`}
      >
        {sortedFiles.map((file) => (
          <div
            key={file.id}
            className={`p-4 border rounded-lg cursor-pointer transition-all ${
              file.isSelected
                ? "border-blue-500 bg-blue-50"
                : "border-gray-200 hover:border-gray-300 hover:bg-gray-50"
            }`}
            onClick={() => handleFileSelect(file.id)}
          >
            <div className="flex items-start justify-between">
              <div className="flex items-center space-x-3">
                <span className="text-2xl">{getFileIcon(file)}</span>
                <div className="flex-1 min-w-0">
                  <div className="font-medium text-gray-900 truncate">
                    {file.name}
                  </div>
                  <div className="text-sm text-gray-500">
                    {file.type === "file" && file.extension && (
                      <span className="mr-2">{file.extension}</span>
                    )}
                    {file.type === "file" && file.size && (
                      <span className="mr-2">{formatFileSize(file.size)}</span>
                    )}
                    <span>
                      {new Date(file.lastModified).toLocaleDateString()}
                    </span>
                  </div>
                </div>
              </div>
              {file.isSelected && <span className="text-blue-500">✓</span>}
            </div>

            {/* Tags */}
            <div className="mt-2 flex flex-wrap gap-1">
              {file.tags.slice(0, 3).map((tag) => (
                <span
                  key={tag}
                  className="px-2 py-1 text-xs bg-gray-100 text-gray-600 rounded-full"
                >
                  {tag}
                </span>
              ))}
              {file.tags.length > 3 && (
                <span className="px-2 py-1 text-xs bg-gray-100 text-gray-600 rounded-full">
                  +{file.tags.length - 3}
                </span>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Empty State */}
      {sortedFiles.length === 0 && (
        <div className="text-center py-12">
          <div className="text-6xl mb-4">📁</div>
          <h3 className="text-xl font-medium text-gray-900 mb-2">
            No files found
          </h3>
          <p className="text-gray-500">
            {searchQuery
              ? "Try adjusting your search criteria"
              : "Start by adding some files"}
          </p>
        </div>
      )}

      {/* Master-only features */}
      {isMaster && (
        <div className="mt-6 p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
          <div className="flex items-center mb-2">
            <span className="text-2xl mr-2">👑</span>
            <span className="font-medium text-yellow-800">Master Controls</span>
          </div>
          <div className="text-sm text-yellow-700">
            Advanced file operations, AI organization, and system-wide file
            management available.
          </div>
        </div>
      )}

      {error && <div className="text-red-500 mb-2">{error}</div>}
      {loading && <div className="text-gray-500 mb-2">Loading...</div>}
      {!isMaster && (
        <div className="mt-4">
          <Button
            onClick={handleRequestWallet}
            disabled={loading || walletRequested}
            className="w-full"
          >
            {loading ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Processing...
              </>
            ) : walletRequested ? (
              "Wallet Request Pending Approval"
            ) : (
              "Request Wallet"
            )}
          </Button>
        </div>
      )}
      {isMaster && (
        <div className="mt-4">
          <h4 className="font-bold mb-2">Pending Wallet Requests</h4>
          {loading && (
            <div className="flex items-center justify-center py-4">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          )}
          {!loading && pendingRequests.length === 0 && (
            <div>No pending requests.</div>
          )}
          {pendingRequests.map((_req) => (
            <Card key={_req.email} className="p-4">
              <div className="flex items-center justify-between">
                <div>
                  <p className="font-medium">{_req.username}</p>
                  <p className="text-sm text-gray-500">{_req.email}</p>
                  <p className="text-xs text-gray-400">
                    Requested: {new Date(_req.requestedAt).toLocaleString()}
                  </p>
                </div>
                <Button
                  onClick={() => handleApproveWallet(_req.email)}
                  disabled={loading}
                >
                  {loading ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : (
                    "Approve"
                  )}
                </Button>
              </div>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";

interface ErrorItem {
  id: number;
  type: string;
  message: string;
  severity: string;
  timestamp: string;
  status: string;
}

interface FixItem {
  errorId: number;
  type: string;
  details: string;
  success: boolean;
  timestamp: string;
  duration: number;
}

interface GitHubActionStatus {
  preCheck: string;
  autoFix: string;
  build: string;
  lint: string;
  deploy: string;
  lastRun: string;
}

const QMOIAutoFixDashboard: React.FC<{ isMaster: boolean }> = ({
  isMaster,
}) => {
  const [errors, setErrors] = useState<ErrorItem[]>([]);
  const [fixes, setFixes] = useState<FixItem[]>([]);
  const [githubStatus, setGitHubStatus] = useState<GitHubActionStatus | null>(
    null
  );
  const [isRunning, setIsRunning] = useState(false);
  const [lastUpdate, setLastUpdate] = useState<string>("");

  const fetchErrorLog = async () => {
    try {
      const mockErrors: ErrorItem[] = [
        {
          id: 1,
          type: "build",
          message: "TypeScript compilation failed",
          severity: "high",
          timestamp: new Date().toISOString(),
          status: "fixed",
        },
        {
          id: 2,
          type: "lint",
          message: "ESLint errors found",
          severity: "medium",
          timestamp: new Date().toISOString(),
          status: "fixed",
        },
        {
          id: 3,
          type: "deploy",
          message: "Vercel deployment failed",
          severity: "high",
          timestamp: new Date().toISOString(),
          status: "pending",
        },
      ];
      setErrors(mockErrors);
    } catch (error) {
      (globalThis.console as any)?.error?.("Failed to fetch error log:", error);
    }
  };

  const fetchFixHistory = async () => {
    try {
      const mockFixes: FixItem[] = [
        {
          errorId: 1,
          type: "typescript-fix",
          details: "Fixed type annotations",
          success: true,
          timestamp: new Date().toISOString(),
          duration: 1500,
        },
        {
          errorId: 2,
          type: "eslint-fix",
          details: "Auto-fixed linting issues",
          success: true,
          timestamp: new Date().toISOString(),
          duration: 800,
        },
        {
          errorId: 3,
          type: "vercel-deploy",
          details: "Force redeploy attempted",
          success: false,
          timestamp: new Date().toISOString(),
          duration: 5000,
        },
      ];
      setFixes(mockFixes);
    } catch (error) {
      (globalThis.console as any)?.error?.("Failed to fetch fix history:", error);
    }
  };

  const fetchGitHubStatus = async () => {
    try {
      const mockStatus: GitHubActionStatus = {
        preCheck: "success",
        autoFix: "success",
        build: "success",
        lint: "success",
        deploy: "success",
        lastRun: new Date().toISOString(),
      };
      setGitHubStatus(mockStatus);
    } catch (error) {
      (globalThis.console as any)?.error?.("Failed to fetch GitHub status:", error);
    }
  };

  useEffect(() => {
    if (isMaster) {
      fetchErrorLog();
      fetchFixHistory();
      fetchGitHubStatus();
      setLastUpdate(new Date().toISOString());
    }
  }, [isMaster]);

  const triggerAutoFix = async () => {
    setIsRunning(true);
    try {
      await new Promise((resolve) => setTimeout(resolve, 3000));
      fetchErrorLog();
      fetchFixHistory();
      fetchGitHubStatus();
      setLastUpdate(new Date().toISOString());
    } catch (error) {
      (globalThis.console as any)?.error?.("Auto-fix failed:", error);
    } finally {
      setIsRunning(false);
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "success":
        return "bg-green-100 text-green-800";
      case "failed":
        return "bg-red-100 text-red-800";
      case "pending":
        return "bg-yellow-100 text-yellow-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case "high":
        return "bg-red-100 text-red-800";
      case "medium":
        return "bg-yellow-100 text-yellow-800";
      case "low":
        return "bg-blue-100 text-blue-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  if (!isMaster)
    return <div className="text-red-500">Access denied: Master only</div>;

  const totalErrors = errors.length;
  const fixedErrors = fixes.filter((f) => f.success).length;
  const remainingErrors = totalErrors - fixedErrors;
  const successRate =
    totalErrors > 0 ? Math.round((fixedErrors / totalErrors) * 100) : 100;

  return (
    <Card className="space-y-4 mt-4">
      <CardHeader>
        <CardTitle className="flex items-center justify-between">
          <span>QMOI Auto-Fix Dashboard</span>
          <div className="flex items-center gap-2">
            <Badge
              className={getStatusColor(isRunning ? "pending" : "success")}
            >
              {isRunning ? "Running" : "Ready"}
            </Badge>
            <Button onClick={triggerAutoFix} disabled={isRunning} size="sm">
              {isRunning ? "Fixing..." : "Trigger Auto-Fix"}
            </Button>
          </div>
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="grid grid-cols-4 gap-4 mb-6">
          <div className="text-center p-3 bg-blue-50 rounded">
            <div className="text-2xl font-bold text-blue-600">
              {totalErrors}
            </div>
            <div className="text-sm text-gray-600">Total Errors</div>
          </div>
          <div className="text-center p-3 bg-green-50 rounded">
            <div className="text-2xl font-bold text-green-600">
              {fixedErrors}
            </div>
            <div className="text-sm text-gray-600">Fixed</div>
          </div>
          <div className="text-center p-3 bg-red-50 rounded">
            <div className="text-2xl font-bold text-red-600">
              {remainingErrors}
            </div>
            <div className="text-sm text-gray-600">Remaining</div>
          </div>
          <div className="text-center p-3 bg-purple-50 rounded">
            <div className="text-2xl font-bold text-purple-600">
              {successRate}%
            </div>
            <div className="text-sm text-gray-600">Success Rate</div>
          </div>
        </div>

        {githubStatus && (
          <div className="mb-6">
            <h4 className="font-semibold mb-2">GitHub Actions Status</h4>
            <div className="grid grid-cols-5 gap-2">
              <Badge className={getStatusColor(githubStatus.preCheck)}>
                Pre-Check
              </Badge>
              <Badge className={getStatusColor(githubStatus.autoFix)}>
                Auto-Fix
              </Badge>
              <Badge className={getStatusColor(githubStatus.build)}>
                Build
              </Badge>
              <Badge className={getStatusColor(githubStatus.lint)}>Lint</Badge>
              <Badge className={getStatusColor(githubStatus.deploy)}>
                Deploy
              </Badge>
            </div>
            <div className="text-xs text-gray-500 mt-1">
              Last run: {new Date(githubStatus.lastRun).toLocaleString()}
            </div>
          </div>
        )}

        <div className="mb-6">
          <h4 className="font-semibold mb-2">All Errors</h4>
          <div className="space-y-2 max-h-40 overflow-y-auto">
            {errors.map((error) => (
              <div
                key={error.id}
                className="flex items-center justify-between p-2 bg-gray-50 rounded"
              >
                <div>
                  <div className="font-medium">{error.type}</div>
                  <div className="text-sm text-gray-600">{error.message}</div>
                </div>
                <div className="flex items-center gap-2">
                  <Badge className={getSeverityColor(error.severity)}>
                    {error.severity}
                  </Badge>
                  <Badge className={getStatusColor(error.status)}>
                    {error.status}
                  </Badge>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="mb-6">
          <h4 className="font-semibold mb-2">Fix History</h4>
          <div className="space-y-2 max-h-40 overflow-y-auto">
            {fixes.map((fix, index) => (
              <div
                key={index}
                className="flex items-center justify-between p-2 bg-gray-50 rounded"
              >
                <div>
                  <div className="font-medium">{fix.type}</div>
                  <div className="text-sm text-gray-600">{fix.details}</div>
                  <div className="text-xs text-gray-500">
                    Error ID: {fix.errorId} | Duration: {fix.duration}ms
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <Badge
                    className={getStatusColor(
                      fix.success ? "success" : "failed"
                    )}
                  >
                    {fix.success ? "SUCCESS" : "FAILED"}
                  </Badge>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="text-xs text-gray-500 text-center">
          Last updated: {new Date(lastUpdate).toLocaleString()}
        </div>
      </CardContent>
    </Card>
  );
};

export default QMOIAutoFixDashboard;

"use client";

import React, {
  createContext,
  useContext,
  useState,
  useEffect,
  ReactNode,
} from "react";
import { avatarsConfig, voiceProfiles } from "./avatarsConfig";
import { getSessionHeaders } from "../../services/qmoiSession";

interface QMOIState {
  // Avatar State
  currentAvatar: string;
  avatarQuality: string;
  avatarEngine: string;

  // Voice State
  currentVoice: string;
  voiceQuality: string;
  voiceVolume: number;

  // Mood & Personality
  mood:
    | "happy"
    | "focused"
    | "curious"
    | "excited"
    | "calm"
    | "professional"
    | "playful"
    | "wise";
  energy: number; // 0-100
  personality:
    | "friendly"
    | "professional"
    | "creative"
    | "analytical"
    | "helpful"
    | "enthusiastic";

  // System State
  isOnline: boolean;
  isProcessing: boolean;
  currentTask: string | null;
  systemHealth: "excellent" | "good" | "fair" | "poor";

  // User Preferences
  autoUpgrade: boolean;
  autoEnhance: boolean;
  dataSaver: boolean;

  // Performance Metrics
  responseTime: number;
  accuracy: number;
  userSatisfaction: number;
}

interface QMOIContextType {
  state: QMOIState;
  updateAvatar: (avatarId: string) => Promise<void>;
  updateVoice: (voiceId: string) => Promise<void>;
  updateMood: (mood: QMOIState["mood"]) => void;
  updateEnergy: (energy: number) => void;
  updatePersonality: (personality: QMOIState["personality"]) => void;
  updateSystemHealth: (health: QMOIState["systemHealth"]) => void;
  updateUserPreferences: (
    preferences: Partial<
      Pick<QMOIState, "autoUpgrade" | "autoEnhance" | "dataSaver">
    >
  ) => void;
  getAvatarInfo: (avatarId: string) => unknown;
  getVoiceInfo: (voiceId: string) => unknown;
  getCompatibleVoice: (avatarId: string) => string;
  getCompatibleAvatar: (voiceId: string) => string;
}

const QMOIContext = createContext<QMOIContextType | undefined>(undefined);

interface QMOIStateProviderProps {
  children: ReactNode;
}

export function QMOIStateProvider({ children }: QMOIStateProviderProps) {
  const [state, setState] = useState<QMOIState>({
    // Avatar State
    currentAvatar: "default",
    avatarQuality: "enhanced",
    avatarEngine: "eva3d-sadtalker",

    // Voice State
    currentVoice: "professional-male",
    voiceQuality: "enhanced",
    voiceVolume: 80,

    // Mood & Personality
    mood: "happy",
    energy: 85,
    personality: "helpful",

    // System State
    isOnline: true,
    isProcessing: false,
    currentTask: null,
    systemHealth: "excellent",

    // User Preferences
    autoUpgrade: true,
    autoEnhance: true,
    dataSaver: false,

    // Performance Metrics
    responseTime: 150,
    accuracy: 98.5,
    userSatisfaction: 95,
  });

  // Load saved state from localStorage
  useEffect(() => {
    const savedState = localStorage.getItem("qmoi-state");
    if (savedState) {
      try {
        const parsedState = JSON.parse(savedState);
        setState((prevState) => ({
          ...prevState,
          ...(parsedState as unknown as Partial<QMOIState>),
        }));
      } catch (error) {
        (globalThis.console as any)?.error?.("Error loading QMOI state:", error);
      }
    }
  }, []);

  // Save state to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem("qmoi-state", JSON.stringify(state));
  }, [state]);

  // Auto-update mood based on time and activity
  useEffect(() => {
    const updateMoodByTime = () => {
      const hour = new Date().getHours();
      let newMood: QMOIState["mood"] = "happy";

      if (hour < 6) newMood = "calm";
      else if (hour < 12) newMood = "excited";
      else if (hour < 18) newMood = "focused";
      else if (hour < 22) newMood = "professional";
      else newMood = "calm";

      setState((prev) => ({ ...prev, mood: newMood }));
    };

    updateMoodByTime();
    const interval = setInterval(updateMoodByTime, 60000); // Update every minute

    return () => clearInterval(interval);
  }, []);

  const updateAvatar = async (avatarId: string) => {
    try {
      setState((prev) => ({
        ...prev,
        isProcessing: true,
        currentTask: "Switching avatar...",
      }));

      // Call API to switch avatar
      const response = await fetch("/api/qmoi/avatars", {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getSessionHeaders() },
        body: JSON.stringify({ action: "switch", avatarId }),
      });

      if (!response.ok) throw new Error("Failed to switch avatar");

      const avatar = avatarsConfig.find((a) => a.id === avatarId);
      setState((prev) => ({
        ...prev,
        currentAvatar: avatarId,
        avatarQuality: avatar?.qualityLevel || "enhanced",
        avatarEngine: avatar?.animationEngine || "eva3d-sadtalker",
        isProcessing: false,
        currentTask: null,
      }));

      // Auto-switch to compatible voice if available
      const compatibleVoice = getCompatibleVoice(avatarId);
      if (compatibleVoice && compatibleVoice !== state.currentVoice) {
        await updateVoice(compatibleVoice);
      }
    } catch (error) {
      (globalThis.console as any)?.error?.("Error updating avatar:", error);
      setState((prev) => ({ ...prev, isProcessing: false, currentTask: null }));
    }
  };

  const updateVoice = async (voiceId: string) => {
    try {
      setState((prev) => ({
        ...prev,
        isProcessing: true,
        currentTask: "Switching voice...",
      }));

      // Call API to switch voice
      const response = await fetch("/api/qmoi/voice-profiles", {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getSessionHeaders() },
        body: JSON.stringify({ action: "switch", voiceId }),
      });

      if (!response.ok) throw new Error("Failed to switch voice");

      const voice = voiceProfiles.find((v) => v.id === voiceId);
      setState((prev) => ({
        ...prev,
        currentVoice: voiceId,
        voiceQuality: voice?.quality || "enhanced",
        isProcessing: false,
        currentTask: null,
      }));
    } catch (error: unknown) {
      const msg =
        error && typeof error === "object" && "message" in error
          ? String((error as { message?: unknown }).message)
          : String(error);
      (globalThis.console as any)?.error?.("Error updating voice:", msg);
      setState((prev) => ({ ...prev, isProcessing: false, currentTask: null }));
    }
  };

  const updateMood = (mood: QMOIState["mood"]) => {
    setState((prev) => ({ ...prev, mood }));
  };

  const updateEnergy = (energy: number) => {
    setState((prev) => ({
      ...prev,
      energy: Math.max(0, Math.min(100, energy)),
    }));
  };

  const updatePersonality = (personality: QMOIState["personality"]) => {
    setState((prev) => ({ ...prev, personality }));
  };

  const updateSystemHealth = (health: QMOIState["systemHealth"]) => {
    setState((prev) => ({ ...prev, systemHealth: health }));
  };

  const updateUserPreferences = (
    preferences: Partial<
      Pick<QMOIState, "autoUpgrade" | "autoEnhance" | "dataSaver">
    >
  ) => {
    setState((prev) => ({ ...prev, ...preferences }));
  };

  const getAvatarInfo = (avatarId: string) => {
    return avatarsConfig.find((a) => a.id === avatarId);
  };

  const getVoiceInfo = (voiceId: string) => {
    return voiceProfiles.find((v) => v.id === voiceId);
  };

  const getCompatibleVoice = (avatarId: string) => {
    const avatar = avatarsConfig.find((a) => a.id === avatarId);
    if (avatar?.voiceProfile) {
      return avatar.voiceProfile;
    }

    // Find compatible voice based on avatar type
    const compatibleVoice = voiceProfiles.find((v) => v.type === avatar?.type);
    return compatibleVoice?.id || "professional-male";
  };

  const getCompatibleAvatar = (voiceId: string) => {
    const compatibleAvatar = avatarsConfig.find(
      (a) => a.voiceProfile === voiceId
    );
    return compatibleAvatar?.id || "default";
  };

  const contextValue: QMOIContextType = {
    state,
    updateAvatar,
    updateVoice,
    updateMood,
    updateEnergy,
    updatePersonality,
    updateSystemHealth,
    updateUserPreferences,
    getAvatarInfo,
    getVoiceInfo,
    getCompatibleVoice,
    getCompatibleAvatar,
  };

  return (
    <QMOIContext.Provider value={contextValue}>{children}</QMOIContext.Provider>
  );
}

export function useQMOIState() {
  const context = useContext(QMOIContext);
  if (context === undefined) {
    throw new Error("useQMOIState must be used within a QMOIStateProvider");
  }
  return context;
}

import React, { useEffect, useState } from "react";
import { getSessionHeaders } from "../../services/qmoiSession";

type LogEntry = {
  timestamp: string;
  action: string;
  type?: "fix" | "cicd" | string;
  result: string;
};

type CICDResult = {
  commitResult?: { success?: boolean; message?: string };
  deployResult?: { success?: boolean; message?: string };
  monitorResult?: { success?: boolean; message?: string };
};

type AutoDevStatus = {
  running?: boolean;
  lastRun?: string;
  lastResult?: {
    fixResults?: unknown[];
    cicdResults?: CICDResult;
    errors?: unknown[];
    testResult?: { success?: boolean };
  };
  daemon?: Record<string, unknown>;
} | null;

function exportToCSV(logs: LogEntry[]) {
  const header = "Timestamp,Action,Result\n";
  const rows = logs
    .map(
      (log) =>
        `"${log.timestamp}","${log.action}","${log.result.replace(/"/g, '""')}"`
    )
    .join("\n");
  const csv = header + rows;
  const blob = new Blob([csv], { type: "text/csv" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = "qmoi_audit_log.csv";
  a.click();
  URL.revokeObjectURL(url);
}

function exportToJSON(logs: LogEntry[]) {
  const blob = new Blob([JSON.stringify(logs, null, 2)], {
    type: "application/json",
  });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = "qmoi_audit_log.json";
  a.click();
  URL.revokeObjectURL(url);
}

const DEPLOY_PLATFORMS = [
  { value: "vercel", label: "Vercel" },
  { value: "heroku", label: "Heroku" },
  { value: "aws", label: "AWS" },
  { value: "azure", label: "Azure" },
  { value: "gcp", label: "GCP" },
];

export default function QMoiAutoDevPanel({
  isMaster = false,
}: {
  isMaster?: boolean;
}) {
  const [status, setStatus] = useState<AutoDevStatus>(null);
  const [loading, setLoading] = useState(true);
  const [daemonAction, setDaemonAction] = useState<"start" | "stop" | null>(
    null
  );
  const [error, setError] = useState<string | null>(null);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [logsLoading, setLogsLoading] = useState(false);
  const [logFilter, setLogFilter] = useState<"all" | "fix" | "cicd">("all");
  const [deployPlatform, setDeployPlatform] = useState("vercel");
  const [forceRunLoading, setForceRunLoading] = useState(false);
  const [forceRunResult, setForceRunResult] = useState<Record<string, unknown> | null>(null);

  async function fetchStatus() {
    setLoading(true);
    setError(null);
    try {
      const _res = await fetch("/api/qmoi/autodev", {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getSessionHeaders() },
        body: JSON.stringify({ action: "full_status" }),
      });
      const data: unknown = await _res.json();
      setStatus(data as AutoDevStatus);
    } catch (_e: unknown) {
      const msg =
        _e && typeof _e === "object" && "message" in _e
          ? String((_e as { message?: unknown }).message)
          : String(_e);
      setError(msg);
    }
    setLoading(false);
  }

  async function handleDaemonControl(action: "start" | "stop") {
    setDaemonAction(action);
    setError(null);
    try {
      const _res = await fetch("/api/qmoi/autodev", {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getSessionHeaders() },
        body: JSON.stringify({
          action:
            action === "start"
              ? "continuous_autofix_start"
              : "continuous_autofix_stop",
        }),
      });
      const data: unknown = await _res.json();
      const d = data as { status?: { running?: boolean } };
      setStatus((prev) => ({
        ...(prev ?? {}),
        daemon: d.status,
        running: d.status?.running,
      }));
    } catch (_e: unknown) {
      const msg =
        _e && typeof _e === "object" && "message" in _e
          ? String((_e as { message?: unknown }).message)
          : String(_e);
      setError(msg);
    }
    setDaemonAction(null);
  }

  async function fetchLogs() {
    setLogsLoading(true);
    setError(null);
    try {
      if (status?.lastResult?.fixResults) {
        const logEntries: LogEntry[] = [];
        if (status.lastResult.fixResults.length > 0) {
          status.lastResult.fixResults.forEach((item: unknown, idx: number) => {
            logEntries.push({
              timestamp: status.lastRun as string,
              action: `Fix Cycle #${idx + 1}`,
              type: "fix",
              result: JSON.stringify(item, null, 2),
            });
          });
        }
        if (status.lastResult.cicdResults) {
          logEntries.push({
            timestamp: status.lastRun ?? new Date().toISOString(),
            action: "CI/CD",
            type: "cicd",
            result: JSON.stringify(status.lastResult.cicdResults, null, 2),
          });
        }
        setLogs(logEntries.slice(-20));
      } else {
        setLogs([]);
      }
    } catch (_e: unknown) {
      const msg =
        _e && typeof _e === "object" && "message" in _e
          ? String((_e as { message?: unknown }).message)
          : String(_e);
      setError(msg);
    }
    setLogsLoading(false);
  }

  async function handleForceRun() {
    setForceRunLoading(true);
    setError(null);
    setForceRunResult(null);
    try {
      const _res = await fetch("/api/qmoi/autodev", {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getSessionHeaders() },
        body: JSON.stringify({ action: "force_run", platform: deployPlatform }),
      });
      const data = await _res.json();
      setForceRunResult(data);
      fetchStatus();
      fetchLogs();
    } catch (_e: unknown) {
      const msg =
        _e && typeof _e === "object" && "message" in _e
          ? String((_e as { message?: unknown }).message)
          : String(_e);
      setError(msg);
    }
    setForceRunLoading(false);
  }

  useEffect(() => {
    if (isMaster) fetchStatus();
  }, [isMaster]);
  useEffect(() => {
    if (isMaster) fetchLogs();
  }, [status]);

  if (!isMaster) return null;

  // Filtering logic
  const filteredLogs = logs.filter((log) => {
    if (logFilter === "all") return true;
    if (logFilter === "fix") return log.type === "fix";
    if (logFilter === "cicd") return log.type === "cicd";
    return true;
  });

  return (
    <div
      style={{
        border: "1px solid #444",
        padding: 16,
        borderRadius: 8,
        background: "#181818",
        color: "#e0ffe0",
        marginTop: 16,
      }}
    >
      <h3>QMOI Auto-Dev Project Manager</h3>
      <div
        style={{
          marginBottom: 12,
          display: "flex",
          alignItems: "center",
          gap: 12,
        }}
      >
        <button
          onClick={fetchStatus}
          style={{
            background: "#222",
            color: "#0f0",
            border: "1px solid #0f0",
            borderRadius: 4,
            padding: "4px 12px",
          }}
        >
          Refresh Status
        </button>
        {status?.running ? (
          <button
            onClick={() => handleDaemonControl("stop")}
            disabled={daemonAction === "stop"}
            style={{
              background: "#f33",
              color: "#fff",
              border: "none",
              borderRadius: 4,
              padding: "4px 12px",
            }}
          >
            {daemonAction === "stop" ? "Stopping..." : "Stop Daemon"}
          </button>
        ) : (
          <button
            onClick={() => handleDaemonControl("start")}
            disabled={daemonAction === "start"}
            style={{
              background: "#0f0",
              color: "#111",
              border: "none",
              borderRadius: 4,
              padding: "4px 12px",
            }}
          >
            {daemonAction === "start" ? "Starting..." : "Start Daemon"}
          </button>
        )}
        <label style={{ marginLeft: 16, color: "#ccc" }}>
          Deploy Platform:
        </label>
        <select
          value={deployPlatform}
          onChange={(_e) =>
            setDeployPlatform((_e.target as HTMLSelectElement).value)
          }
          style={{
            background: "#111",
            color: "#0ff",
            border: "1px solid #0ff",
            borderRadius: 4,
            padding: "2px 8px",
          }}
        >
          {DEPLOY_PLATFORMS.map((p) => (
            <option key={p.value} value={p.value}>
              {p.label}
            </option>
          ))}
        </select>
        <button
          onClick={handleForceRun}
          disabled={forceRunLoading}
          style={{
            background: "#09f",
            color: "#fff",
            border: "none",
            borderRadius: 4,
            padding: "4px 16px",
            fontWeight: 600,
          }}
        >
          {forceRunLoading ? "Running..." : "Force Run"}
        </button>
      </div>
      {forceRunResult && (
        <div
          style={{
            background: "#222",
            color: forceRunResult.success ? "#0f0" : "#f33",
            padding: 8,
            borderRadius: 6,
            marginBottom: 8,
          }}
        >
          <b>Force Run Result:</b> {String((forceRunResult as any)?.message)}
          {(forceRunResult as any)?.platform && (
            <span style={{ marginLeft: 8, color: "#0ff" }}>
              ({String((forceRunResult as any)?.platform)})
            </span>
          )}
        </div>
      )}
      {loading ? (
        <p>Loading...</p>
      ) : error ? (
        <p style={{ color: "#f66" }}>{error}</p>
      ) : (
        <div style={{ background: "#222", padding: 12, borderRadius: 8 }}>
          <div>
            <b>Daemon Running:</b>{" "}
            {status?.running ? (
              <span style={{ color: "#0f0" }}>Yes</span>
            ) : (
              <span style={{ color: "#f33" }}>No</span>
            )}
          </div>
          <div>
            <b>Last Run:</b> {status?.lastRun || "N/A"}
          </div>
          <div style={{ marginTop: 8 }}>
            <b>Last Result:</b>
          </div>
          {status?.lastResult ? (
            <div
              style={{
                fontSize: "0.95em",
                background: "#181818",
                padding: 8,
                borderRadius: 6,
                marginBottom: 8,
              }}
            >
              <div>
                <b>Errors:</b> {status.lastResult.errors?.length || 0}
              </div>
              <div>
                <b>Test Result:</b>{" "}
                {status.lastResult.testResult?.success ? (
                  <span style={{ color: "#0f0" }}>Passed</span>
                ) : (
                  <span style={{ color: "#f33" }}>Failed</span>
                )}
              </div>
              <div>
                <b>Commit/Push:</b>{" "}
                {status.lastResult.cicdResults?.commitResult?.success ? (
                  <span style={{ color: "#0f0" }}>Success</span>
                ) : (
                  <span style={{ color: "#f33" }}>Failed</span>
                )}{" "}
                {status.lastResult.cicdResults?.commitResult?.message && (
                  <span style={{ color: "#ccc", marginLeft: 8 }}>
                    {status.lastResult.cicdResults?.commitResult?.message}
                  </span>
                )}
              </div>
              <div>
                <b>Deploy:</b>{" "}
                {status.lastResult.cicdResults?.deployResult?.success ? (
                  <span style={{ color: "#0f0" }}>Success</span>
                ) : (
                  <span style={{ color: "#f33" }}>Failed</span>
                )}{" "}
                {status.lastResult.cicdResults?.deployResult?.message && (
                  <span style={{ color: "#ccc", marginLeft: 8 }}>
                    {status.lastResult.cicdResults?.deployResult?.message}
                  </span>
                )}
              </div>
              <div>
                <b>Monitor:</b>{" "}
                {status.lastResult.cicdResults?.monitorResult?.success ? (
                  <span style={{ color: "#0f0" }}>Healthy</span>
                ) : (
                  <span style={{ color: "#f33" }}>Unhealthy</span>
                )}{" "}
                {status.lastResult.cicdResults?.monitorResult?.message && (
                  <span style={{ color: "#ccc", marginLeft: 8 }}>
                    {status.lastResult.cicdResults?.monitorResult?.message}
                  </span>
                )}
              </div>
              <div style={{ marginTop: 8 }}>
                <b>Fix Results:</b>
                <pre
                  style={{
                    background: "#111",
                    color: "#0ff",
                    borderRadius: 4,
                    padding: 8,
                    overflowX: "auto",
                  }}
                >
                  {JSON.stringify(status.lastResult.fixResults, null, 2)}
                </pre>
              </div>
            </div>
          ) : (
            <div style={{ color: "#888" }}>No recent results.</div>
          )}
        </div>
      )}
      <div style={{ marginTop: 24 }}>
        <h4>Audit Log / History</h4>
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 12,
            marginBottom: 8,
          }}
        >
          <button
            onClick={fetchLogs}
            style={{
              background: "#222",
              color: "#0ff",
              border: "1px solid #0ff",
              borderRadius: 4,
              padding: "2px 10px",
            }}
          >
            Refresh Logs
          </button>
          <button
            onClick={() => exportToCSV(filteredLogs)}
            style={{
              background: "#222",
              color: "#ff0",
              border: "1px solid #ff0",
              borderRadius: 4,
              padding: "2px 10px",
            }}
          >
            Export CSV
          </button>
          <button
            onClick={() => exportToJSON(filteredLogs)}
            style={{
              background: "#222",
              color: "#0f0",
              border: "1px solid #0f0",
              borderRadius: 4,
              padding: "2px 10px",
            }}
          >
            Export JSON
          </button>
          <label style={{ marginLeft: 16, color: "#ccc" }}>Filter: </label>
          <select
            value={logFilter}
            onChange={(_e) =>
              setLogFilter(
                (_e.target as HTMLSelectElement).value as "all" | "fix" | "cicd"
              )
            }
            style={{
              background: "#111",
              color: "#0ff",
              border: "1px solid #0ff",
              borderRadius: 4,
              padding: "2px 8px",
            }}
          >
            <option value="all">All</option>
            <option value="fix">Fix Cycles</option>
            <option value="cicd">CI/CD</option>
          </select>
        </div>
        {logsLoading ? (
          <div style={{ color: "#ff0" }}>Loading logs...</div>
        ) : (
          <div
            style={{
              maxHeight: 220,
              overflowY: "auto",
              background: "#181818",
              border: "1px solid #333",
              borderRadius: 6,
              padding: 8,
            }}
          >
            {filteredLogs.length === 0 ? (
              <div style={{ color: "#888" }}>No logs available.</div>
            ) : (
              filteredLogs.map((log, i) => (
                <div
                  key={i}
                  style={{
                    marginBottom: 10,
                    borderBottom: "1px solid #333",
                    paddingBottom: 6,
                  }}
                >
                  <div style={{ color: "#0ff", fontSize: "0.95em" }}>
                    <b>{log.timestamp}</b>{" "}
                    <span style={{ color: "#fff" }}>{log.action}</span>
                  </div>
                  <pre
                    style={{
                      background: "#111",
                      color: "#eee",
                      borderRadius: 4,
                      padding: 6,
                      marginTop: 2,
                      fontSize: "0.92em",
                      overflowX: "auto",
                    }}
                  >
                    {log.result}
                  </pre>
                </div>
              ))
            )}
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState } from "react";

