"use client";
import React, { useEffect } from "react";

type Props = {
  children: React.ReactNode;
  attribute?: string;
  defaultTheme?: "light" | "dark" | "system";
  enableSystem?: boolean;
  // When true, temporarily disables CSS transitions during theme changes to avoid flashes
  disableTransitionOnChange?: boolean;
};

export function ThemeProvider({
  children,
  attribute = "data-theme",
  defaultTheme = "system",
  enableSystem = true,
  disableTransitionOnChange = false,
}: Props) {
  useEffect(() => {
    try {
      let theme = defaultTheme;
      if (
        defaultTheme === "system" &&
        enableSystem &&
        typeof window !== "undefined" &&
        window.matchMedia
      ) {
        theme = window.matchMedia("(prefers-color-scheme: dark)").matches
          ? "dark"
          : "light";
      }

      // Optionally disable transitions during theme change to avoid visual flashes
      if (disableTransitionOnChange && typeof document !== "undefined") {
        document.documentElement.classList.add("qmoi-disable-theme-transition");
        // Remove the class after a short delay so normal transitions resume
        setTimeout(() => {
          document.documentElement.classList.remove(
            "qmoi-disable-theme-transition"
          );
        }, 250);
      }

      document.documentElement.setAttribute(attribute, theme as string);
    } catch (_e) {
      // fail silently in tests
    }
  }, [attribute, defaultTheme, enableSystem, disableTransitionOnChange]);

  return <>{children}</>;
}

export default ThemeProvider;

/**
 * Centralized API configuration for production and development environments.
 * Adapters and components import from this file to get the correct base URL and endpoints.
 */

export type Environment = "development" | "staging" | "production" | "local";

export interface ApiConfig {
  environment: Environment;
  baseUrl: string;
  endpoints: {
    media: string;
    verify: string;
    mail: string;
    files: string;
    emergency: string;
    youtube: string;
    health: string;
  };
  timeout: number;
  retries: number;
}

/**
 * Get the current environment (from NEXT_PUBLIC_ENV or default to 'development')
 */
function getCurrentEnvironment(): Environment {
  if (typeof window !== "undefined") {
    // Browser environment
    const env = (globalThis as any).__ENV__ || process.env.NEXT_PUBLIC_ENV;
    return (env as Environment) || "development";
  }
  // Server environment
  return (process.env.NEXT_PUBLIC_ENV as Environment) || "development";
}

/**
 * Configuration per environment
 */
const configMap: Record<Environment, ApiConfig> = {
  local: {
    environment: "local",
    baseUrl: "http://localhost:8000",
    endpoints: {
      media: "/api/media",
      verify: "/api/verify",
      mail: "/api/mail",
      files: "/api/files",
      emergency: "/api/emergency",
      youtube: "/api/youtube/download",
      health: "/api/health",
    },
    timeout: 10000,
    retries: 2,
  },
  development: {
    environment: "development",
    baseUrl: process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000",
    endpoints: {
      media: "/api/media",
      verify: "/api/verify",
      mail: "/api/mail",
      files: "/api/files",
      emergency: "/api/emergency",
      youtube: "/api/youtube/download",
      health: "/api/health",
    },
    timeout: 10000,
    retries: 2,
  },
  staging: {
    environment: "staging",
    baseUrl: process.env.NEXT_PUBLIC_API_URL || "https://staging-api.qmoi.app",
    endpoints: {
      media: "/api/media",
      verify: "/api/verify",
      mail: "/api/mail",
      files: "/api/files",
      emergency: "/api/emergency",
      youtube: "/api/youtube/download",
      health: "/api/health",
    },
    timeout: 15000,
    retries: 3,
  },
  production: {
    environment: "production",
    baseUrl: process.env.NEXT_PUBLIC_API_URL || "https://api.qmoi.app",
    endpoints: {
      media: "/api/media",
      verify: "/api/verify",
      mail: "/api/mail",
      files: "/api/files",
      emergency: "/api/emergency",
      youtube: "/api/youtube/download",
      health: "/api/health",
    },
    timeout: 20000,
    retries: 3,
  },
};

/**
 * Get the API configuration for the current environment
 */
export function getApiConfig(): ApiConfig {
  const env = getCurrentEnvironment();
  const config = configMap[env];
  return {
    ...config,
    baseUrl: process.env.NEXT_PUBLIC_API_URL || config.baseUrl,
  };
}

/**
 * Build a full URL for an API endpoint
 */
export function buildUrl(endpoint: string): string {
  const config = getApiConfig();
  return `${config.baseUrl}${endpoint}`;
}

/**
 * Get a specific endpoint URL
 */
export function getEndpoint(key: keyof ApiConfig["endpoints"]): string {
  const config = getApiConfig();
  return buildUrl(config.endpoints[key]);
}

export default getApiConfig;

