import { useState, useEffect, useCallback } from "react";
import { authManager } from "../auth/AuthManager";

interface User {
  id: string;
  username: string;
  email: string;
  role: "master" | "sister" | "user";
  preferences: {
    theme: "light" | "dark" | "system";
    notifications: boolean;
    tradingEnabled: boolean;
  };
}

interface AuthState {
  user: User | null;
  loading: boolean;
  error: string | null;
}

export function useAuth() {
  const [state, setState] = useState<AuthState>({
    user: null,
    loading: true,
    error: null,
  });

  useEffect(() => {
    // Check for existing session
    const sessionId = localStorage.getItem("sessionId");
    if (sessionId) {
      validateSession(sessionId);
    } else {
      setState((prev) => ({ ...prev, loading: false }));
    }
  }, []);

  const validateSession = async (sessionId: string) => {
    try {
      const isValid = await authManager.validateSession(sessionId);
      if (isValid) {
        const user = await authManager.getUser(sessionId);
        setState({
          user,
          loading: false,
          error: null,
        });
      } else {
        // Clear invalid session
        localStorage.removeItem("sessionId");
        setState({
          user: null,
          loading: false,
          error: null,
        });
      }
    } catch (error) {
      setState({
        user: null,
        loading: false,
        error: "Failed to validate session",
      });
    }
  };

  const login = useCallback(async (email: string, password: string) => {
    try {
      setState((prev) => ({ ...prev, loading: true, error: null }));
      const session = await authManager.login(
        email,
        password,
        window.location.hostname,
        navigator.userAgent,
      );
      localStorage.setItem("sessionId", session.id);
      const user = await authManager.getUser(session.id);
      setState({
        user,
        loading: false,
        error: null,
      });
    } catch (error) {
      setState({
        user: null,
        loading: false,
        error: "Invalid credentials",
      });
    }
  }, []);

  const logout = useCallback(async () => {
    try {
      const sessionId = localStorage.getItem("sessionId");
      if (sessionId) {
        await authManager.logout(sessionId);
        localStorage.removeItem("sessionId");
      }
      setState({
        user: null,
        loading: false,
        error: null,
      });
    } catch (error) {
      setState((prev) => ({
        ...prev,
        error: "Failed to logout",
      }));
    }
  }, []);

  const register = useCallback(
    async (username: string, email: string, password: string) => {
      try {
        setState((prev) => ({ ...prev, loading: true, error: null }));
        const user = await authManager.registerUser(username, email, password);
        setState((prev) => ({
          ...prev,
          loading: false,
          error: null,
        }));
        return user;
      } catch (error) {
        setState({
          user: null,
          loading: false,
          error: "Failed to register",
        });
        throw error;
      }
    },
    [],
  );

  const hasAccess = useCallback(async (feature: string) => {
    const sessionId = localStorage.getItem("sessionId");
    if (!sessionId) {
      return false;
    }
    return authManager.hasAccess(sessionId, feature);
  }, []);

  const updatePreferences = useCallback(
    async (preferences: Partial<User["preferences"]>) => {
      try {
        const sessionId = localStorage.getItem("sessionId");
        if (!sessionId) {
          throw new Error("No active session");
        }
        const user = await authManager.updateUserPreferences(
          sessionId,
          preferences,
        );
        setState((prev) => ({
          ...prev,
          user,
        }));
      } catch (error) {
        setState((prev) => ({
          ...prev,
          error: "Failed to update preferences",
        }));
      }
    },
    [],
  );

  return {
    ...state,
    login,
    logout,
    register,
    hasAccess,
    updatePreferences,
  };
}

import { useState, useEffect, useCallback } from "react";

interface AutoProject {
  id: string;
  name: string;
  description: string;
  status: "planned" | "in-progress" | "completed" | "failed";
  type:
    | "web-app"
    | "mobile-app"
    | "game"
    | "animation"
    | "tool"
    | "api"
    | "automation";
  priority: "low" | "medium" | "high" | "critical";
  startedAt?: string;
  completedAt?: string;
  estimatedDuration: number; // in minutes
  actualDuration?: number;
  technologies: string[];
  features: string[];
  documentation: boolean;
  testing: boolean;
  deployment: boolean;
}

interface DailyPlan {
  date: string;
  projects: AutoProject[];
  totalEstimatedTime: number;
  status: "draft" | "active" | "completed";
}

interface UseAutoProjectsReturn {
  projects: AutoProject[];
  dailyPlan: DailyPlan | null;
  isLoading: boolean;
  createProject: (
    project: Omit<AutoProject, "id" | "status" | "startedAt">
  ) => Promise<void>;
  updateProjectStatus: (
    id: string,
    status: AutoProject["status"]
  ) => Promise<void>;
  generateDailyPlan: () => Promise<void>;
  notifyMaster: (message: string) => Promise<void>;
  createWhatsAppGroup: () => Promise<void>;
  postToWhatsAppGroup: (message: string) => Promise<void>;
  getProjectStats: () => {
    total: number;
    completed: number;
    inProgress: number;
    planned: number;
    successRate: number;
  };
}

export const useAutoProjects = (): UseAutoProjectsReturn => {
  const [projects, setProjects] = useState<AutoProject[]>([]);
  const [dailyPlan, setDailyPlan] = useState<DailyPlan | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  // Load projects from localStorage
  useEffect(() => {
    const savedProjects = localStorage.getItem("qmoi-auto-projects");
    if (savedProjects) {
      try {
        setProjects(JSON.parse(savedProjects) as AutoProject[]);
      } catch (_e) {
        (globalThis.console as any)?.error?.("Failed to parse saved projects:", _e);
      }
    }

    const savedDailyPlan = localStorage.getItem("qmoi-daily-plan");
    if (savedDailyPlan) {
      try {
        setDailyPlan(JSON.parse(savedDailyPlan) as DailyPlan);
      } catch (_e) {
        (globalThis.console as any)?.error?.("Failed to parse saved daily plan:", _e);
      }
    }
  }, []);

  // Save projects to localStorage whenever they change
  useEffect(() => {
    localStorage.setItem("qmoi-auto-projects", JSON.stringify(projects));
  }, [projects]);

  // Save daily plan to localStorage whenever it changes
  useEffect(() => {
    if (dailyPlan) {
      localStorage.setItem("qmoi-daily-plan", JSON.stringify(dailyPlan));
    }
  }, [dailyPlan]);

  const createProject = useCallback(
    async (projectData: Omit<AutoProject, "id" | "status" | "startedAt">) => {
      setIsLoading(true);
      try {
        const newProject: AutoProject = {
          ...projectData,
          id: `project-${Date.now()}`,
          status: "planned",
          startedAt: undefined,
        };

        setProjects((prev) => [...prev, newProject]);

        // Notify master about new project
        await notifyMaster(
          `🆕 New project planned: ${newProject.name}\nType: ${newProject.type}\nPriority: ${newProject.priority}\nEstimated time: ${newProject.estimatedDuration} minutes`
        );
      } catch (error) {
        (globalThis.console as any)?.error?.("Error creating project:", error);
      } finally {
        setIsLoading(false);
      }
    },
    []
  );

  const updateProjectStatus = useCallback(
    async (id: string, status: AutoProject["status"]) => {
      setIsLoading(true);
      try {
        setProjects((prev) =>
          prev.map((project) => {
            if (project.id === id) {
              const updatedProject = { ...project, status };

              if (status === "in-progress" && !project.startedAt) {
                updatedProject.startedAt = new Date().toISOString();
              }

              if (status === "completed" && !project.completedAt) {
                updatedProject.completedAt = new Date().toISOString();
                if (project.startedAt) {
                  const startTime = new Date(project.startedAt).getTime();
                  const endTime = new Date().getTime();
                  updatedProject.actualDuration = Math.round(
                    (endTime - startTime) / (1000 * 60)
                  ); // Convert to minutes
                }
              }

              return updatedProject;
            }
            return project;
          })
        );

        // Notify master about status change
        const project = projects.find((p) => p.id === id);
        if (project) {
          await notifyMaster(
            `📊 Project status updated: ${project.name}\nNew status: ${status}${
              status === "completed"
                ? " ✅"
                : status === "in-progress"
                ? " 🔄"
                : " 📋"
            }`
          );
        }
      } catch (error) {
        (globalThis.console as any)?.error?.("Error updating project status:", error);
      } finally {
        setIsLoading(false);
      }
    },
    [projects]
  );

  const generateDailyPlan = useCallback(async () => {
    setIsLoading(true);
    try {
      // Generate 10+ projects for the day
      const projectTypes: AutoProject["type"][] = [
        "web-app",
        "mobile-app",
        "game",
        "animation",
        "tool",
        "api",
        "automation",
      ];
      const priorities: AutoProject["priority"][] = [
        "low",
        "medium",
        "high",
        "critical",
      ];

      const newProjects: AutoProject[] = [];

      for (let i = 0; i < 12; i++) {
        // Generate 12 projects
        const project: AutoProject = {
          id: `daily-project-${Date.now()}-${i}`,
          name: `Auto Project ${i + 1}`,
          description: `Automatically generated project ${
            i + 1
          } for daily plan`,
          status: "planned",
          type: projectTypes[Math.floor(Math.random() * projectTypes.length)],
          priority: priorities[Math.floor(Math.random() * priorities.length)],
          estimatedDuration: Math.floor(Math.random() * 120) + 30, // 30-150 minutes
          technologies: ["React", "TypeScript", "Node.js", "Python"],
          features: [
            "Responsive Design",
            "API Integration",
            "Database",
            "Authentication",
          ],
          documentation: true,
          testing: true,
          deployment: true,
        };
        newProjects.push(project);
      }

      const plan: DailyPlan = {
        date: new Date().toISOString().split("T")[0],
        projects: newProjects,
        totalEstimatedTime: newProjects.reduce(
          (sum, p) => sum + p.estimatedDuration,
          0
        ),
        status: "active",
      };

      setDailyPlan(plan);
      setProjects((prev) => [...prev, ...newProjects]);

      // Notify master about daily plan
      await notifyMaster(
        `📅 Daily plan generated for ${plan.date}\nTotal projects: ${
          newProjects.length
        }\nEstimated time: ${Math.round(
          plan.totalEstimatedTime / 60
        )} hours\nStatus: ${plan.status}`
      );

      // Post to WhatsApp group
      await postToWhatsAppGroup(
        `📋 Daily Plan - ${plan.date}\n\nProjects planned: ${
          newProjects.length
        }\nEstimated time: ${Math.round(
          plan.totalEstimatedTime / 60
        )} hours\n\nProjects:\n${newProjects
          .map(
            (p, i) =>
              `${i + 1}. ${p.name} (${p.type}) - ${p.estimatedDuration}min`
          )
          .join("\n")}`
      );
    } catch (error) {
      (globalThis.console as any)?.error?.("Error generating daily plan:", error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const notifyMaster = useCallback(async (message: string) => {
    try {
      // Simulate WhatsApp notification to master
      console.log("📱 WhatsApp notification to master:", message);

      // In real implementation, this would call the WhatsApp API
