        return (_res as any)(
          (ctx as any).status(200),
          (ctx as any).json(payload),
        );
      }
      const response = new Response(JSON.stringify(payload), {
        status: 200,
        headers: new Headers({ "content-type": "application/json" }),
      });
      if (typeof _res === "function") {
        return (_res as any)(response);
      }
      return response;
    }),
