    helpers.get(
      "http://localhost/api/qmoi/status",
      (_req: unknown, _res: unknown, ctx: unknown) => {
        try {
          debug(
            "HANDLER: absolute status handler invoked, url=",
            ((_req as any)._request && ((_req as any)._request as any).url) ||
