        }
        return response;
      },
    ),
    helpers.post("/api/qmoi/payload", (_req: unknown, _res: unknown, ctx: unknown) => {
      // in rest handlers, _req.url is a URL instance
      try {
        debug(
          "HANDLER: payload handler invoked, keys=",
          Object.keys(_req),
