      if (typeof d === "object" && d !== null) {
        const obj = d as {
          command?: VoiceCommand;
          transcript?: string;
          confidence?: number;
        };
        callback({
          command: obj.command as VoiceCommand,
          transcript: String(obj.transcript ?? ""),
          confidence: Number(obj.confidence ?? 0),
        });
