// Manage a persistent `qmoi_session_id` and headers for requests
export function getSessionId(): string {
  if (typeof window === "undefined") return "server";
  try {
    let sid = localStorage.getItem("qmoi_session_id");
    if (!sid) {
      // try cookie
      const m = document.cookie.match(/(?:^|; )qmoi_session_id=([^;]+)/);
      if (m) sid = decodeURIComponent(m[1]);
    }
    if (!sid) {
      sid = `s_${Date.now().toString(36)}_${Math.random()
        .toString(36)
        .slice(2, 8)}`;
      localStorage.setItem("qmoi_session_id", sid);
      // set cookie for client too
      try {
        document.cookie = `qmoi_session_id=${encodeURIComponent(
          sid
        )}; Path=/; Max-Age=${60 * 60 * 24 * 365}; SameSite=Lax`;
      } catch (_e) { void _e; }
    }
    return sid;
  } catch (_e) {
    return `s_${Date.now().toString(36)}`;
  }
}

export function getSessionHeaders(): Record<string, string> {
  const headers: Record<string, string> = {};
  try {
    const sid = getSessionId();
    if (sid) headers["X-QMOI-SESSION"] = sid;
    const role =
      typeof window !== "undefined"
        ? localStorage.getItem("qmoi_role")
        : undefined;
    if (role) headers["X-QMOI-ROLE"] = role;
    const user =
      typeof window !== "undefined"
        ? localStorage.getItem("qmoi_user")
        : undefined;
    if (user) headers["X-QMOI-USER"] = user;
  } catch (_e) { void _e; }
  return headers;
}

export function setProfile(profile: {
  name?: string;
  role?: string;
  userId?: string;
}) {
  try {
    if (profile.role) localStorage.setItem("qmoi_role", profile.role);
    if (profile.name) localStorage.setItem("qmoi_user", profile.name);
    if (profile.userId) localStorage.setItem("qmoi_userid", profile.userId);
  } catch (_e) { void _e; }
}

import { app, Notification } from "electron";
import path from "path";

// Module-scoped alias for Electron `app` with conservative typing to avoid misuse.
type ElectronDockLike = {
  setIcon?: (p: string) => void;
  setTooltip?: (t: string) => void;
  hide?: () => void;
};

type ElectronAppLike = {
  dock?: ElectronDockLike;
  getAppPath?: () => string;
  on?: (event: string, handler: (...args: unknown[]) => void) => void;
};

const _app = app as unknown as ElectronAppLike;

interface TaskbarOptions {
  icon: string;
  tooltip: string;
  showInTaskbar: boolean;
  notifications: boolean;
}

interface NotificationEvent {
  preventDefault: () => void;
}

interface NotificationData {
  title: string;
  body: string;
  icon?: string;
}

export class TaskbarManager {
  private static instance: TaskbarManager;
  private _options: TaskbarOptions;

  private constructor(_options: TaskbarOptions) {
    this._options = _options;
    this.initialize();
  }

  public static getInstance(_options: TaskbarOptions): TaskbarManager {
    if (!TaskbarManager.instance) {
      TaskbarManager.instance = new TaskbarManager(_options);
    }
    return TaskbarManager.instance;
  }

  private initialize(): void {
    if (this._options.showInTaskbar) {
      // Set application icon
      const iconPath = path.join(_app.getAppPath?.() ?? "", this._options.icon);
      ((globalThis as any)._app?.dock as any)?.setIcon?.(iconPath);

      // Set tooltip
      ((globalThis as any)._app?.dock as any)?.setTooltip?.(this._options.tooltip);

      // Enable notifications if requested
      if (this._options.notifications) {
        this.setupNotifications();
      }
    }
  }

  private setupNotifications(): void {
    // Setup notification handlers
    (_app as any).on?.("ready", () => {
      // Register notification handlers
      this.registerNotificationHandlers();
    });
  }

  private registerNotificationHandlers(): void {
    // Handle different types of notifications
    (globalThis as any)._app?.on?.(
      "notification-click",
      (_event: NotificationEvent, notification: NotificationData) => {
        // Handle notification clicks
        console.log("Notification clicked:", notification);
      }
    );

    (globalThis as any)._app?.on?.(
      "notification-close",
      (_event: NotificationEvent, notification: NotificationData) => {
        // Handle notification closes
        console.log("Notification closed:", notification);
      }
    );
  }

  public showNotification(title: string, body: string): void {
    if (this._options.notifications) {
      // Show system notification using a conservatively-typed constructor
      const NotificationConstructor = Notification as unknown as {
        new (data: NotificationData): unknown;
      };
      // Provide a safe icon path even if getAppPath is unavailable
      new NotificationConstructor({
        title,
        body,
        icon: path.join(_app.getAppPath?.() ?? "", this._options.icon),
      });
    }
  }

  public updateTooltip(tooltip: string): void {
    if (this._options.showInTaskbar) {
      (globalThis as any)._app?.dock?.setTooltip(tooltip);
    }
  }

  public updateIcon(iconPath: string): void {
    if (this._options.showInTaskbar) {
      const fullPath = path.join(_app.getAppPath?.() ?? "", iconPath);
      (globalThis as any)._app?.dock?.setIcon(fullPath);
    }
  }

  public toggleTaskbarVisibility(show: boolean): void {
    this._options.showInTaskbar = show;
    if (show) {
      this.initialize();
    } else {
      (globalThis as any)._app?.dock?.hide();
    }
  }

  public toggleNotifications(enable: boolean): void {
    this._options.notifications = enable;
    if (enable) {
      this.setupNotifications();
    }
  }
}

// Export a function to create the taskbar manager
export function createTaskbarManager(_options: TaskbarOptions): TaskbarManager {
  return TaskbarManager.getInstance(_options);
}
